const configured=(()=>{
const cfg = {
  versiya_shablona: 'client-core-0.16-sales-brain-llm-followup-v1',
  kompaniya_kod: 'katona',
  // Закрытый тест: добавьте Telegram ID тестировщиков, иначе все входящие сообщения отклоняются.
