    }
  ],

  operator: {
    vklyuchen: true,
    sobytiya_vklyucheny: true,
    sluzhebnaya_gruppa_id: null,
    lichnye_uvedomleniya: true,
    menedzhery_telegram_id: [],
    tema_prefiks: 'Клиент'
  },

  golos: {
    // Включить после подтверждения собственного STT-сервиса Катоны.
    vklyuchen: false,
