    ]
  },

  prodazhi: {
    chasovoy_poyas: 'Europe/Moscow',

    etapy: [
      'novoe_obrashchenie',
      'privetstvie',
      'vyyavlenie_potrebnosti',
      'podbor_resheniya',
      'rabota_s_vozrazheniyami',
      'predlozhenie_celevogo_deystviya',
      'celevoe_deystvie',
      'peredacha_cheloveku',
