    pervoe_minut: 180,
    vtoroe_minut: 1440,
    okno_napominaniya_minut: 60,
    poterya_posle_vtorogo_minut: 1440,

    // Для подтверждённого переноса контакта на конкретную будущую дату.
    otlozhennyy_vtoroe_chasov: 24,
    otlozhennyy_okno_chasov: 12,
    otlozhennyy_poterya_dney: 7,

    // Используются только как аварийный fallback, если LLM не вернула валидный текст.
    tekst_1:
      'Подскажите, вопрос ещё актуален? Если хотите, продолжим с того места, где остановились.',

    tekst_2:
      'Не хочу быть навязчивым. Если задача ещё актуальна, напишите — помогу определить следующий шаг.'
  },

  preduprezhdeniya: {
    tekst_1:
      'Пожалуйста, используйте этот чат по вопросам компании и её услуг. Я помогу по теме обращения.',

    tekst_2:
      'Это второе предупреждение: бот предназначен только для вопросов по теме компании и её услуг.',

    tekst_3:
      'Это третье предупреждение. Автоматические ответы в этом чате будут остановлены. При необходимости менеджер сможет разблокировать диалог.'
  },

  peredacha: {
    tekst:
      'Передаю диалог менеджеру. Он продолжит общение здесь.'
  },

  zapret_iniciativy: {
    tekst:
      'Хорошо, больше не будем отправлять инициативные сообщения. Если понадобится помощь, просто напишите.'
  },

  media: {
    tekst_predlozheniya:
      'Я не могу распознать информацию на фото или видео. Если там важная информация, я могу позвать менеджера. Позвать?',

    tekst_otkaza:
      'Хорошо. Тогда, пожалуйста, опишите вопрос текстом или отправьте голосовое сообщение.',

    tekst_nepodderzhivaemogo:
      'Я могу работать с текстом и голосовыми сообщениями. Если важная информация находится во вложении, напишите об этом текстом.'
  },

  model: {
    guard: 'gpt-4.1-mini',
    planner: 'gpt-4.1-mini',
    answer: 'gpt-4.1-mini',
    embedding: 'text-embedding-3-large',
    razmernost: 1024,
    guard_max_tokens: 500,
    planner_max_tokens: 1000,
    otvet_max_tokens: 1200
  },

  rag: {
    profil_indeksa_id: null,
    candidate_top_k: 12,
    evidence_max: 8,
    porog_pohozhesti: 0.01
  },

  obrabotka: {
    max_zadaniy_za_raz: 1,
    max_napominaniy_za_raz: 20,
    max_zerkala_za_raz: 1
  }
};

const rl = cfg.bezopasnost?.limit_chastoty || {};
const rem = cfg.napominaniya || {};

const est_aktivnyy_kanal =
  Object.values(cfg.kanaly || {})
    .some(v => v?.vklyuchen === true);

const ready =
  est_aktivnyy_kanal &&
  cfg.opisanie_biznesa !== 'ЗАПОЛНИТЬ ПРИ ВНЕДРЕНИИ' &&
  cfg.razreshennye_temy.length > 0 &&
  cfg.cel.nazvanie !== 'ЗАПОЛНИТЬ ПРИ ВНЕДРЕНИИ' &&
  (
    !cfg.operator.vklyuchen ||
    cfg.operator.sobytiya_vklyucheny !== true ||
    Boolean(cfg.operator.sluzhebnaya_gruppa_id)
  ) &&
  Boolean(cfg.bezopasnost?.region_telefona) &&
  Number.isInteger(rl.okno_sekund) &&
  rl.okno_sekund > 0 &&
  Number.isInteger(rl.limit_soobshcheniy) &&
  rl.limit_soobshcheniy > 0 &&
  Number.isInteger(rem.okno_napominaniya_minut) &&
  rem.okno_napominaniya_minut > 0;

return $input.all().map(i => ({
  json: {
    ...i.json,
    _nastroyki: cfg,
    profil_kompanii_gotov: ready
  },
  binary: i.binary
}));
})();
return configured.flatMap(item=>{
  if(item.json.tip_zapuska) return [item];
  const authorized = item.json._nastroyki?.testovye_telegram_user_id || [];
  const incoming = item.json.body || {};
  const senderId = incoming.message?.from?.id ?? incoming.edited_message?.from?.id ?? incoming.callback_query?.from?.id ?? null;
  // Closed pilot: drop unknown senders before any database entry or AI call.
  if (!Array.isArray(authorized) || !authorized.some(v => String(v) === String(senderId))) return [];
  const $json={...item.json,tip_zapuska:'vhod_klienta',kanal_vhoda:'telegram'};
  const normalized=(()=>{
const root=$json||{},body=root.body||{},m=body.message||body.edited_message||null,cb=body.callback_query||null,cfg=root._nastroyki||{};
const kanal=String(root.kanal_vhoda||'').trim();
if(kanal!=='telegram') throw new Error('Telegram-нормализатор получил чужой канал: '+kanal);
const channelCfg=cfg.kanaly?.[kanal]||{};
if(channelCfg.vklyuchen!==true) throw new Error('Канал telegram отключён в настройках компании');

let tip='drugoe',dbTip='system',text='',chat=null,from=null,mid=null,file=null,size=null,dur=null,mime=null,cbid=null,sourceDate=null,eventType='message';
if(m){
  chat=m.chat?.id??null;from=m.from?.id??null;mid=m.message_id??null;
  sourceDate=m.date?new Date(Number(m.date)*1000).toISOString():null;
  if(typeof m.text==='string'){tip='text';dbTip='text';text=m.text;}
  else if(m.voice){tip='golos';dbTip='voice';file=m.voice.file_id;size=m.voice.file_size??null;dur=m.voice.duration??null;mime=m.voice.mime_type||'audio/ogg';}
  else if(m.photo){tip='foto';dbTip='photo';const p=m.photo[m.photo.length-1];file=p?.file_id||null;size=p?.file_size??null;text=m.caption||'';}
  else if(m.video){tip='video';dbTip='video';file=m.video.file_id;size=m.video.file_size??null;dur=m.video.duration??null;mime=m.video.mime_type||'video/mp4';text=m.caption||'';}
  else if(m.document){tip='dokument';dbTip='document';file=m.document.file_id;size=m.document.file_size??null;mime=m.document.mime_type||null;text=m.caption||'';}
  else if(m.sticker){tip='stiker';dbTip='sticker';file=m.sticker.file_id;}
}else if(cb){
  eventType='callback';tip='callback';cbid=cb.id||null;chat=cb.message?.chat?.id??null;from=cb.from?.id??null;mid=cb.message?.message_id??null;
  sourceDate=cb.message?.date?new Date(Number(cb.message.date)*1000).toISOString():null;
  const data=String(cb.data||'');
  if(data==='media_take'||data.startsWith('media_take:')){dbTip='text';text='Позвать менеджера';}
  else if(data==='media_no'||data.startsWith('media_no:')){dbTip='text';text='Продолжить без менеджера';}
  else{dbTip='system';text='';}
}
if(body.update_id===undefined||body.update_id===null)throw new Error('Нет Telegram update_id');
if(chat===null||from===null)throw new Error('Не удалось определить chat_id/from_id');

const accountCode=String(channelCfg.akkaunt_kod||'client');
const accountId=`${cfg.kompaniya_kod||'company'}:${cfg.sreda||'env'}:${kanal}:${accountCode}`;
const rawFingerprint=`${kanal}:${body.update_id}:${JSON.stringify(body)}`;
const telegram={update_id:body.update_id,chat_id:chat,from_id:from,message_id:mid,tip_kontenta:tip,tekst:text,file_id:file,file_size:size,duration:dur,mime_type:mime,callback_query_id:cbid,raw:body};

const db_vhod={
  versiya_formata:1,
  operaciya_id:`tg_client_ingress:${accountId}:${body.update_id}`,
  klyuch_idempotentnosti:`${kanal}:${accountId}:update:${body.update_id}`,
  hash_soderzhaniya:rawFingerprint,
  kanal,
  akkaunt_kanala_id:accountId,
  vneshnee_sobytie_id:String(body.update_id),
  vneshniy_polzovatel_id:String(from),
  vneshniy_dialog_id:String(chat),
  vneshnee_soobshchenie_id:mid===null?null:String(mid),
  tip_sobytiya:eventType,
  tip_soobshcheniya:dbTip,
  tekst_ishodnyy:text,
  vremya_istochnika:sourceDate,
  vremya_priema:new Date().toISOString(),
  trassirovka_id:`${kanal}:${accountId}:${body.update_id}`,
  versiya_workflow:String(cfg.versiya_shablona||'client-core-draft-0.3'),
  versiya_prompta:'ai-migration-pending-v0.2',
  payload_ishodnyy:body,
  sluzhebnyy_chat_id:cfg.operator?.sluzhebnaya_gruppa_id===null||cfg.operator?.sluzhebnaya_gruppa_id===undefined?'':String(cfg.operator.sluzhebnaya_gruppa_id),
  bezopasnaya_podpis_klienta:`Клиент •••${String(from).slice(-4)}`,
  nachalnyy_etap:'novoe_obrashchenie',
  prioritet:0
};

return [{json:{_nastroyki:cfg,profil_kompanii_gotov:root.profil_kompanii_gotov,kanal_vhoda:kanal,telegram,db_vhod}}];
  })();
  return [{...normalized[0],json:{...normalized[0].json,tip_zapuska:'vhod_klienta'}}];
});

