        /(?<![\p{L}\p{N}_])(меня\s+зовут|мо[её]\s+имя)\s+([А-ЯЁA-Z][А-ЯЁA-Za-zа-яё-]{1,40})/giu,
        '$1 <PERSON>'
      );
  }

  function safeValue(v) {
    if (typeof v === 'string') {
      return safeString(v);
    }

    if (Array.isArray(v)) {
      return v.map(safeValue);
    }

    if (v && typeof v === 'object') {
      return Object.fromEntries(
        Object.entries(v).map(
          ([k, z]) => [k, safeValue(z)]
        )
      );
    }

    return v;
  }

  const aiMemory = {
    rezume: safeString(x.rezume_dialoga || ''),
    pamyat: safeValue(
      (
        Array.isArray(x.pamyat_okno)
