      )
    ),
    fakty: safeValue(x.vazhnye_fakty || {}),
    tekushchiy_etap:
      x.ai_kontekst?.dialog?.etap || null
  };

  // Полные методики хранятся внутри workflow, но в OpenAI отправляются
  // только те 0–2 навыка, которые planner выбрал для текущего хода.
  const skillLibrary = {
