      'Давай только подтверждённые факты, гарантии и кейсы из evidence.',
      'Если подтверждения нет, честно скажи об ограничении и предложи безопасный способ получить подтверждение или подключить менеджера.',
      'Не обещай то, что компания не может доказать.'
    ].join(' '),

    sleduyushchiy_shag: [
      'Цель: переводить интерес в конкретное действие без резкого давления.',
      'Перед предложением следующего шага проверь, что он логично следует из разговора.',
      'Формулируй один простой и понятный шаг: уточнить данные, получить расчёт, согласовать консультацию, оставить контакт или другой шаг, разрешённый целью компании.',
      'Объясни клиенту, зачем этот шаг ему полезен.',
      'Не проси имя и телефон механически, если клиент ещё не понимает ценность или уже сообщил эти данные.'
    ].join(' ')
  };

  const allowedSkills = new Set(
    (Array.isArray(c.prodazhi?.navyki_katalog)
      ? c.prodazhi.navyki_katalog
      : []
    ).map(v => String(v?.kod || '')).filter(Boolean)
  );

  const requestedSkills = Array.isArray(x.plan_poiska?.navyki)
    ? x.plan_poiska.navyki
    : [];

  const maxSkills = Math.max(
    0,
    Math.min(
      2,
      Number(c.prodazhi?.max_navykov_na_hod || 2)
    )
  );

  const selectedSkills = [...new Set(
    requestedSkills
      .map(v => String(v || ''))
      .filter(v =>
        allowedSkills.has(v) &&
        Object.prototype.hasOwnProperty.call(skillLibrary, v)
      )
  )].slice(0, maxSkills);

  const skillInstructions = selectedSkills.map(kod => ({
    kod,
    instrukciya: skillLibrary[kod]
  }));

  const salesSituation = String(
    x.plan_poiska?.situaciya_prodazhi ||
    'prodolzhenie_dialoga'
  );

  const schema = {
