    vneshnee_otvet_na_id:source.vneshnee_soobshchenie_id||null,
    tekst_ishodnyy:String($json.tekst_otveta||''),
    tekst_obezlichennyy:String($json.tekst_otveta||''),
    ozhidaetsya_otvet:wait,
    prichina_resheniya:String($json.reshenie?.prichina_etapa||tip),
    payload:{
